const queryClient = new QueryClient();

const nav = [
  { href: '/', label: 'Command center', icon: LayoutDashboard },
  { href: '/incidents', label: 'Incidents', icon: AlertCircle },
  { href: '/memory', label: 'Memory explorer', icon: BrainCircuit },
  { href: '/postmortems', label: 'Post-mortems', icon: FileText },
  { href: '/demo', label: 'Demo lab', icon: Microscope },
  { href: '/settings', label: 'Settings', icon: Settings2 },
];

function cx(...classes: Array<string | false | undefined>) { return classes.filter(Boolean).join(' '); }
function when(value?: string | null) { return value ? new Date(value).toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—'; }
function tone(value?: string) {
  const v = (value || '').toLowerCase();
  if (v.includes('critical') || v.includes('failed') || v.includes('error')) return 'text-rose-300 bg-rose-400/10 border-rose-400/25';
  if (v.includes('high') || v.includes('degraded') || v.includes('pending')) return 'text-amber-200 bg-amber-300/10 border-amber-300/25';
  if (v.includes('resolved') || v.includes('passed') || v.includes('healthy') || v.includes('approved')) return 'text-emerald-300 bg-emerald-300/10 border-emerald-300/25';
  return 'text-cyan-200 bg-cyan-300/10 border-cyan-300/25';
}
function Badge({ children }: { children: ReactNode }) { return <span className="inline-flex items-center rounded border px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[.12em]">{children}</span>; }
function Skeleton({ className = '' }: { className?: string }) { return <div className={cx('animate-pulse rounded bg-white/[.06]', className)} />; }
function LoadingPanel({ label = 'Loading console data' }: { label?: string }) { return <div className="rounded-lg border border-border/70 bg-card/70 p-8"><div className="flex items-center gap-3 text-sm text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin text-primary" /><span data-testid="status-loading">{label}</span></div><div className="mt-6 space-y-3"><Skeleton className="h-3 w-3/4" /><Skeleton className="h-3 w-1/2" /></div></div>; }
function ErrorPanel({ onRetry, label = 'Unable to load this view' }: { onRetry?: () => void; label?: string }) { return <div className="rounded-lg border border-rose-400/25 bg-rose-400/[.06] p-6" data-testid="state-error"><div className="flex items-start gap-3"><XCircle className="mt-0.5 h-5 w-5 text-rose-300" /><div><p className="font-semibold text-rose-100">{label}</p><p className="mt-1 text-sm text-rose-200/70">The API returned no usable response. Try again when the service is reachable.</p>{onRetry && <button data-testid="button-retry" onClick={onRetry} className="mt-4 inline-flex items-center gap-2 rounded border border-rose-300/30 px-3 py-1.5 text-xs font-semibold text-rose-100 hover:bg-rose-300/10"><RefreshCw className="h-3.5 w-3.5" /> Retry</button>}</div></div></div>; }
function EmptyPanel({ title, detail }: { title: string; detail: string }) { return <div className="rounded-lg border border-dashed border-border bg-card/35 p-10 text-center" data-testid="state-empty"><Archive className="mx-auto h-7 w-7 text-muted-foreground/60" /><p className="mt-3 font-semibold">{title}</p><p className="mx-auto mt-1 max-w-sm text-sm text-muted-foreground">{detail}</p></div>; }
function PageTitle({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: ReactNode }) { return <div className="mb-7 flex flex-wrap items-end justify-between gap-4 reveal"><div><p className="font-mono text-[10px] uppercase tracking-[.22em] text-primary">{eyebrow}</p><h1 className="mt-2 font-display text-4xl tracking-tight text-foreground">{title}</h1><p className="mt-2 max-w-2xl text-sm text-muted-foreground">{detail}</p></div>{action}</div>; }
function SectionHeading({ icon: Icon, label, meta }: { icon: typeof Activity; label: string; meta?: string }) { return <div className="mb-4 flex items-center justify-between"><div className="flex items-center gap-2"><Icon className="h-4 w-4 text-primary" /><h2 className="text-sm font-semibold tracking-wide">{label}</h2></div>{meta && <span className="font-mono text-[10px] uppercase tracking-wider text-muted-foreground">{meta}</span>}</div>; }

function Shell({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  return <div className="min-h-[100dvh] bg-background text-foreground">
    <aside className={cx('fixed inset-y-0 left-0 z-30 flex w-64 flex-col border-r border-sidebar-border bg-sidebar transition-transform duration-200 md:translate-x-0', mobileOpen ? 'translate-x-0' : '-translate-x-full')}>
      <div className="flex h-16 items-center gap-3 border-b border-sidebar-border px-5">
        <div className="grid h-8 w-8 place-items-center rounded bg-primary text-primary-foreground"><Command className="h-4 w-4" /></div>
        <div><div className="font-display text-xl leading-none text-sidebar-foreground">MemoryOps</div><div className="mt-1 font-mono text-[9px] uppercase tracking-[.18em] text-primary">incident cognition</div></div>
      </div>
      <div className="mx-4 mt-5 rounded border border-amber-300/20 bg-amber-200/[.06] px-3 py-2.5"><div className="flex items-center gap-2 text-[10px] font-semibold uppercase tracking-[.15em] text-amber-200"><CircleDot className="h-3 w-3" /> Simulated fixtures</div><p className="mt-1 text-[11px] leading-relaxed text-amber-100/55">No live systems are affected. Remediation always requires approval.</p></div>
      <nav className="mt-6 flex-1 space-y-1 px-3">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} onClick={() => setMobileOpen(false)} className={cx('group flex items-center gap-3 rounded px-3 py-2.5 text-sm transition-colors', location === href ? 'bg-sidebar-accent text-sidebar-accent-foreground' : 'text-sidebar-foreground/65 hover:bg-sidebar-accent/70 hover:text-sidebar-foreground')}><Icon className={cx('h-4 w-4', location === href ? 'text-primary' : 'text-sidebar-foreground/45')} /><span>{label}</span>{href === '/incidents' && <span className="ml-auto rounded bg-rose-400/10 px-1.5 py-0.5 font-mono text-[9px] text-rose-200">live</span>}</Link>)}</nav>
      <div className="border-t border-sidebar-border p-4"><div className="flex items-center gap-2"><div className="h-2 w-2 rounded-full bg-emerald-300 shadow-[0_0_10px_hsl(151_55%_54%/.7)]" /><span className="font-mono text-[10px] uppercase tracking-[.14em] text-sidebar-foreground/60">Console online</span></div><p className="mt-2 font-mono text-[9px] text-sidebar-foreground/35">region us-central1 · fixture mode</p></div>
    </aside>
    {mobileOpen && <button aria-label="Close menu" data-testid="button-close-menu" onClick={() => setMobileOpen(false)} className="fixed inset-0 z-20 bg-black/50 md:hidden" />}
    <main className="min-h-[100dvh] md:pl-64"><header className="sticky top-0 z-10 flex h-16 items-center justify-between border-b border-border/70 bg-background/90 px-4 backdrop-blur md:px-8"><button aria-label="Open menu" data-testid="button-open-menu" onClick={() => setMobileOpen(true)} className="rounded p-2 text-muted-foreground hover:bg-muted md:hidden"><Menu className="h-5 w-5" /></button><div className="hidden items-center gap-2 text-xs text-muted-foreground md:flex"><Terminal className="h-3.5 w-3.5 text-primary" /><span className="font-mono">ops-room /</span><span className="text-foreground">{location === '/' ? 'command-center' : location.slice(1)}</span></div><div className="ml-auto flex items-center gap-3"><span className="hidden font-mono text-[10px] uppercase tracking-wider text-muted-foreground sm:inline">all systems simulated</span><div className="flex items-center gap-2 rounded border border-border bg-card px-2.5 py-1.5"><div className="h-1.5 w-1.5 rounded-full bg-primary" /><span className="font-mono text-[10px] text-primary">READY</span></div></div></header><div className="console-grid min-h-[calc(100dvh-4rem)] px-4 py-7 md:px-8 md:py-9">{children}</div></main>
  </div>;
}

function Metric({ label, value, note, icon: Icon, accent = 'text-primary' }: { label: string; value: ReactNode; note: string; icon: typeof Activity; accent?: string }) { return <div className="rounded-lg border border-border/70 bg-card/85 p-4 transition-colors hover:border-primary/35"><div className="flex items-start justify-between"><span className="font-mono text-[10px] uppercase tracking-[.15em] text-muted-foreground">{label}</span><Icon className={cx('h-4 w-4', accent)} /></div><div className="mt-3 font-display text-3xl" data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`}>{value}</div><p className="mt-1 text-xs text-muted-foreground">{note}</p></div>; }

function Overview() {
  const dashboard = useGetDashboard();
  const health = useHealthCheck();
  if (dashboard.isLoading) return <><PageTitle eyebrow="01 / command center" title="Operational picture" detail="A compact read on the incident surface and the memory available to your responders." /><LoadingPanel /></>;
  if (dashboard.isError || !dashboard.data) return <><PageTitle eyebrow="01 / command center" title="Operational picture" detail="A compact read on the incident surface and the memory available to your responders." /><ErrorPanel onRetry={() => dashboard.refetch()} /></>;
  const d = dashboard.data;
  const active = d.recent_incidents?.find((i) => i.status !== 'resolved') || d.recent_incidents?.[0];
  const max = Math.max(...(d.severity_breakdown || []).map((x) => x.count), 1);
  return <div className="mx-auto max-w-[1500px]"><PageTitle eyebrow="01 / command center" title="Operational picture" detail="Live evidence, remembered context, and human decisions in one view." action={<Link href="/incidents" data-testid="link-view-incidents" className="inline-flex items-center gap-2 rounded bg-primary px-3.5 py-2 text-xs font-bold text-primary-foreground hover:brightness-110">Open incident queue <ArrowRight className="h-3.5 w-3.5" /></Link>} />
    <div className="mb-6 flex items-center gap-2 border-y border-border/60 py-2 font-mono text-[10px] uppercase tracking-[.14em] text-muted-foreground"><span className="text-primary">●</span> Fixture stream connected <span className="mx-1 text-border">/</span> {health.data ? `api ${health.data.status}` : 'checking api'} <span className="ml-auto">{new Date().toLocaleTimeString()}</span></div>
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Metric label="Active incidents" value={d.active_incidents} note="requiring an operator" icon={AlertCircle} accent="text-rose-300" /><Metric label="Resolved incidents" value={d.resolved_incidents} note="in the current fixture set" icon={CheckCircle2} accent="text-emerald-300" /><Metric label="Mean time to restore" value={d.mttr_minutes == null ? '—' : `${d.mttr_minutes}m`} note="from incident start" icon={Clock3} accent="text-amber-200" /><Metric label="Recurrence signals" value={d.recurrence_count} note="patterns worth remembering" icon={History} accent="text-violet-300" /><Metric label="Hindsight memories" value={d.memory_count} note="available to reasoning" icon={BrainCircuit} /></div>
    <div className="mt-6 grid gap-6 xl:grid-cols-[1.25fr_.75fr]"><div className="space-y-6">
      {active && <section className="scanline overflow-hidden rounded-lg border border-rose-300/25 bg-[linear-gradient(110deg,hsl(2_72%_58%/.1),transparent_55%)] p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><span className="h-2 w-2 animate-pulse rounded-full bg-rose-300" /><span className="font-mono text-[10px] uppercase tracking-[.18em] text-rose-200">Active incident · {active.public_id}</span></div><Badge>{active.severity}</Badge></div><h2 className="mt-4 max-w-2xl font-display text-3xl text-rose-50">{active.title}</h2><p className="mt-2 max-w-2xl text-sm text-rose-100/65">{active.summary}</p><div className="mt-5 flex flex-wrap items-center gap-3"><Link href={`/investigation/${active.id}`} data-testid={`link-investigate-${active.id}`} className="inline-flex items-center gap-2 rounded bg-rose-300 px-3 py-2 text-xs font-bold text-slate-950 hover:bg-rose-200">Enter investigation <ArrowRight className="h-3.5 w-3.5" /></Link><span className="font-mono text-[10px] text-rose-100/50">{active.service} · started {when(active.started_at)}</span></div></section>}
      <section className="rounded-lg border border-border/70 bg-card/75 p-5"><SectionHeading icon={Gauge} label="Severity distribution" meta="fixture window" /><div className="space-y-4">{(d.severity_breakdown || []).map((point) => <div key={point.severity} data-testid={`row-severity-${point.severity}`}><div className="mb-1.5 flex justify-between text-xs"><span className="capitalize text-muted-foreground">{point.severity}</span><span className="font-mono text-foreground">{point.count}</span></div><div className="h-2 rounded bg-muted"><div className={cx('h-2 rounded transition-all', point.severity.toLowerCase().includes('critical') ? 'bg-rose-300' : point.severity.toLowerCase().includes('high') ? 'bg-amber-300' : 'bg-primary')} style={{ width: `${Math.max(point.count / max * 100, 3)}%` }} /></div></div>)}</div></section>
    </div><div className="space-y-6"><section className="rounded-lg border border-border/70 bg-card/75 p-5"><SectionHeading icon={Network} label="Service posture" meta="now" /><div className="space-y-1">{(d.services || []).map((s) => <div key={s.name} data-testid={`row-service-${s.name}`} className="flex items-center gap-3 rounded px-2 py-2.5 hover:bg-muted/60"><div className={cx('h-2 w-2 rounded-full', s.status.toLowerCase().includes('healthy') ? 'bg-emerald-300' : 'bg-amber-300')} /><span className="flex-1 text-sm">{s.name}</span><span className="text-right font-mono text-[10px] uppercase text-muted-foreground">{s.status}</span></div>)}</div></section>
      <section className="rounded-lg border border-border/70 bg-card/75 p-5"><SectionHeading icon={Activity} label="Recent incidents" /><div className="space-y-1">{(d.recent_incidents || []).slice(0, 5).map((i) => <Link href={`/investigation/${i.id}`} key={i.id} data-testid={`link-recent-${i.id}`} className="flex items-center gap-3 rounded px-2 py-2.5 hover:bg-muted/60"><span className={cx('h-1.5 w-1.5 rounded-full', i.status === 'resolved' ? 'bg-emerald-300' : 'bg-rose-300')} /><span className="min-w-0 flex-1 truncate text-sm">{i.title}</span><span className="font-mono text-[10px] text-muted-foreground">{i.public_id}</span><ChevronRight className="h-3 w-3 text-muted-foreground" /></Link>)}</div></section>
    </div></div>
  </div>;
}

function IncidentsPage() {
  const [query, setQuery] = useState(''); const [status, setStatus] = useState(''); const [open, setOpen] = useState(false);
  const params = useMemo(() => status ? { status } : undefined, [status]);
  const incidents = useListIncidents(params); const create = useCreateIncident(); const [form, setForm] = useState({ title: '', service: '', severity: 'high', summary: '' });
  const rows = (incidents.data || []).filter((i) => !query || `${i.title} ${i.service} ${i.public_id}`.toLowerCase().includes(query.toLowerCase()));
  const submit = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ data: form }, { onSuccess: () => { setOpen(false); setForm({ title: '', service: '', severity: 'high', summary: '' }); queryClient.invalidateQueries({ queryKey: getListIncidentsQueryKey(params) }); } }); };
  return <div className="mx-auto max-w-[1500px]"><PageTitle eyebrow="02 / incident queue" title="Incidents" detail="Search the operational record, then open an investigation when signal needs reasoning." action={<button data-testid="button-create-incident" onClick={() => setOpen(true)} className="inline-flex items-center gap-2 rounded bg-primary px-3.5 py-2 text-xs font-bold text-primary-foreground hover:brightness-110"><Plus className="h-4 w-4" /> Create incident</button>} />
    <div className="mb-4 flex flex-wrap gap-2"><div className="relative min-w-[240px] flex-1"><Search className="absolute left-3 top-2.5 h-4 w-4 text-muted-foreground" /><input data-testid="input-search-incidents" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search title, service, public ID" className="h-9 w-full rounded border border-input bg-card pl-9 pr-3 text-sm outline-none focus:border-primary" /></div><div className="flex items-center gap-2 rounded border border-input bg-card px-2.5"><Filter className="h-3.5 w-3.5 text-muted-foreground" /><select data-testid="select-incident-status" value={status} onChange={(e) => setStatus(e.target.value)} className="h-8 bg-transparent text-xs outline-none"><option value="">All statuses</option><option value="new">New</option><option value="investigating">Investigating</option><option value="awaiting_approval">Awaiting approval</option><option value="resolved">Resolved</option></select></div></div>
    {incidents.isLoading ? <LoadingPanel /> : incidents.isError ? <ErrorPanel onRetry={() => incidents.refetch()} /> : rows.length === 0 ? <EmptyPanel title="No incidents match" detail="Try a wider search or create a new incident from the command center." /> : <div className="overflow-x-auto rounded-lg border border-border/70 bg-card/75"><table className="w-full min-w-[760px] text-left"><thead className="border-b border-border/70 bg-muted/30 font-mono text-[10px] uppercase tracking-[.15em] text-muted-foreground"><tr><th className="px-5 py-3">Incident</th><th className="px-5 py-3">Service</th><th className="px-5 py-3">Severity</th><th className="px-5 py-3">Status</th><th className="px-5 py-3">Started</th><th className="px-5 py-3" /></tr></thead><tbody className="divide-y divide-border/60">{rows.map((i) => <tr key={i.id} data-testid={`row-incident-${i.id}`} className="group hover:bg-muted/25"><td className="px-5 py-4"><Link href={`/investigation/${i.id}`} data-testid={`link-incident-${i.id}`} className="block"><span className="font-mono text-[10px] text-primary">{i.public_id}</span><span className="mt-1 block max-w-sm truncate text-sm font-medium group-hover:text-primary">{i.title}</span></Link></td><td className="px-5 py-4 text-sm text-muted-foreground">{i.service}</td><td className="px-5 py-4"><Badge><span className={tone(i.severity)}>{i.severity}</span></Badge></td><td className="px-5 py-4"><Badge><span className={tone(i.status)}>{i.status}</span></Badge></td><td className="px-5 py-4 font-mono text-[10px] text-muted-foreground">{when(i.started_at)}</td><td className="px-5 py-4 text-right"><ChevronRight className="ml-auto h-4 w-4 text-muted-foreground group-hover:text-primary" /></td></tr>)}</tbody></table></div>}
    {open && <div className="fixed inset-0 z-50 grid place-items-center bg-black/70 p-4"><form onSubmit={submit} className="w-full max-w-lg rounded-lg border border-border bg-card p-6 shadow-2xl"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-widest text-primary">New record</p><h2 className="mt-1 font-display text-2xl">Create incident</h2></div><button type="button" data-testid="button-close-create" onClick={() => setOpen(false)} className="rounded p-2 text-muted-foreground hover:bg-muted"><X className="h-4 w-4" /></button></div><div className="mt-5 space-y-4">{[['title','Title'],['service','Service'],['summary','Summary']].map(([key,label]) => <label key={key} className="block text-xs font-medium text-muted-foreground">{label}<input required={key !== 'summary'} data-testid={`input-incident-${key}`} value={form[key as keyof typeof form]} onChange={(e) => setForm({ ...form, [key]: e.target.value })} className="mt-1.5 h-9 w-full rounded border border-input bg-background px-3 text-sm text-foreground outline-none focus:border-primary" /></label>)}<label className="block text-xs font-medium text-muted-foreground">Severity<select data-testid="select-create-severity" value={form.severity} onChange={(e) => setForm({ ...form, severity: e.target.value })} className="mt-1.5 h-9 w-full rounded border border-input bg-background px-3 text-sm"><option>critical</option><option>high</option><option>medium</option><option>low</option></select></label></div><button disabled={create.isPending} data-testid="button-submit-incident" className="mt-6 flex h-10 w-full items-center justify-center gap-2 rounded bg-primary text-xs font-bold text-primary-foreground disabled:opacity-60">{create.isPending && <Loader2 className="h-4 w-4 animate-spin" />} Create simulated incident</button>{create.isError && <p className="mt-3 text-xs text-rose-300" data-testid="status-create-error">Could not create the incident.</p>}</form></div>}
  </div>;
}

function Workflow({ investigation }: { investigation: Investigation }) { return <div className="flex flex-wrap gap-2">{investigation.steps.map((step, index) => <div key={step.name} data-testid={`step-workflow-${step.name}`} className={cx('flex items-center gap-2 rounded border px-3 py-2', step.status === 'complete' || step.status === 'completed' ? 'border-emerald-300/25 bg-emerald-300/[.06]' : step.status === 'active' ? 'border-primary/35 bg-primary/[.08]' : 'border-border bg-card/50')}><span className={cx('grid h-5 w-5 place-items-center rounded-full font-mono text-[10px]', step.status === 'complete' || step.status === 'completed' ? 'bg-emerald-300/15 text-emerald-200' : step.status === 'active' ? 'bg-primary/15 text-primary' : 'bg-muted text-muted-foreground')}>{step.status === 'complete' || step.status === 'completed' ? <Check className="h-3 w-3" /> : index + 1}</span><span className="text-xs">{step.label}</span></div>)}</div>; }

function InvestigationPage() {
  const { incidentId = '' } = useParams<{ incidentId: string }>(); const [tab, setTab] = useState('evidence');
  const incident = useGetIncident(incidentId); const investigation = useGetInvestigation(incidentId); const trace = useGetMemoryTrace(incidentId);
  const start = useStartInvestigation(); const approve = useApproveRemediation(); const reject = useRejectRemediation(); const verify = useVerifyIncident();
  const refresh = () => { incident.refetch(); investigation.refetch(); };
  if (incident.isLoading || investigation.isLoading) return <LoadingPanel label="Loading investigation surface" />;
  if (incident.isError || investigation.isError || !incident.data || !investigation.data) return <ErrorPanel onRetry={refresh} />;
  const i = incident.data; const inv = investigation.data;
  const decision = (action: 'approve' | 'reject') => { if (!inv.proposal) return; const fn = action === 'approve' ? approve : reject; fn.mutate({ incidentId, data: { proposal_id: inv.proposal.id, reason: action === 'approve' ? 'Approved by operator in simulated console.' : 'Rejected by operator in simulated console.' } }, { onSuccess: (next) => queryClient.setQueryData(getGetInvestigationQueryKey(incidentId), next) }); };
  return <div className="mx-auto max-w-[1500px]"><div className="mb-5 flex flex-wrap items-center gap-2 text-xs text-muted-foreground"><Link href="/incidents" data-testid="link-back-incidents" className="hover:text-primary">Incidents</Link><ChevronRight className="h-3 w-3" /><span className="font-mono text-primary">{i.public_id}</span></div><div className="mb-6 flex flex-wrap items-start justify-between gap-4"><div><div className="flex items-center gap-3"><h1 className="font-display text-4xl">{i.title}</h1><Badge><span className={tone(i.severity)}>{i.severity}</span></Badge></div><p className="mt-2 text-sm text-muted-foreground">{i.service} · {i.status} · opened {when(i.started_at)}</p></div><div className="flex gap-2">{!inv.run_id && <button data-testid="button-start-investigation" onClick={() => start.mutate({ incidentId }, { onSuccess: refresh })} className="inline-flex items-center gap-2 rounded bg-primary px-3 py-2 text-xs font-bold text-primary-foreground"><Play className="h-3.5 w-3.5" /> Start investigation</button>}<span className="rounded border border-amber-300/25 bg-amber-300/[.06] px-3 py-2 font-mono text-[10px] uppercase tracking-wider text-amber-200">Simulated · approval gated</span></div></div><Workflow investigation={inv} />
      <div className="mt-6 grid gap-6 xl:grid-cols-[1.4fr_.6fr]"><div className="space-y-6"><section className="rounded-lg border border-border/70 bg-card/75"><div className="flex flex-wrap border-b border-border/70 px-4 pt-3">{['evidence','reasoning','hindsight','trace','timeline','postmortem'].map((name) => <button key={name} data-testid={`tab-investigation-${name}`} onClick={() => setTab(name)} className={cx('border-b-2 px-3 py-2.5 text-xs capitalize transition-colors', tab === name ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground')}>{name}</button>)}</div><div className="p-5">{tab === 'evidence' && <EvidenceTab incident={i} investigation={inv} />}{tab === 'reasoning' && <ReasoningTab investigation={inv} />}{tab === 'hindsight' && <HindsightTab investigation={inv} />}{tab === 'trace' && <TraceTab trace={trace.data} loading={trace.isLoading} />}{tab === 'timeline' && <TimelineTab investigation={inv} />}{tab === 'postmortem' && <PostmortemEmbed incidentId={incidentId} />}</div></section></div>
      <div className="space-y-6"><section className="rounded-lg border border-amber-300/25 bg-amber-300/[.05] p-5"><SectionHeading icon={Zap} label="Remediation gate" meta="human approval" />{inv.proposal ? <><div className="rounded border border-border bg-background/40 p-3"><p className="font-mono text-[10px] uppercase tracking-wider text-amber-200">{inv.proposal.action_type} · {inv.proposal.target}</p><p className="mt-2 text-sm">{inv.proposal.rationale}</p><p className="mt-3 text-xs text-muted-foreground">Expected: {inv.proposal.expected_result}</p><div className="mt-3"><Badge><span className={tone(inv.proposal.status)}>{inv.proposal.status}</span></Badge></div></div><div className="mt-4 flex gap-2"><button disabled={approve.isPending || inv.proposal.status !== 'proposed'} data-testid="button-approve-remediation" onClick={() => decision('approve')} className="flex-1 rounded bg-emerald-300 px-3 py-2 text-xs font-bold text-slate-950 disabled:opacity-40">{approve.isPending ? 'Approving…' : 'Approve simulation'}</button><button disabled={reject.isPending || inv.proposal.status !== 'proposed'} data-testid="button-reject-remediation" onClick={() => decision('reject')} className="rounded border border-rose-300/30 px-3 py-2 text-xs font-semibold text-rose-200 disabled:opacity-40">Reject</button></div></> : <p className="text-sm text-muted-foreground">No remediation proposal has been produced yet.</p>}</section>{inv.execution && <section className="rounded-lg border border-border/70 bg-card/75 p-5"><SectionHeading icon={Activity} label="Simulated execution" /><div className="flex items-center gap-2"><span className={cx('h-2 w-2 rounded-full', inv.execution.status === 'passed' || inv.execution.status === 'succeeded' ? 'bg-emerald-300' : 'bg-amber-300')} /><span className="text-sm">{inv.execution.detail}</span></div>{inv.verification ? <><div className="my-4 border-t border-border/60" /><div className="flex items-center gap-2 text-sm"><ShieldCheck className={cx('h-4 w-4', inv.verification.passed ? 'text-emerald-300' : 'text-rose-400')} />Verification ({inv.verification.passed ? 'Passed' : 'Failed'}): {inv.verification.observed_state}</div></> : <div className="mt-3 text-xs text-amber-200/80">Synthetic execution recorded. Verification required before resolution.</div>}<button disabled={verify.isPending || Boolean(inv.verification?.passed)} data-testid="button-verify-incident" onClick={() => verify.mutate({ incidentId }, { onSuccess: refresh })} className={cx("mt-4 inline-flex items-center gap-2 rounded border px-3 py-2 text-xs transition-colors", inv.verification?.passed ? "border-emerald-300/40 bg-emerald-300/10 text-emerald-300 cursor-default" : "border-primary/30 text-primary hover:bg-primary/10")}><ShieldCheck className="h-3.5 w-3.5" /> {verify.isPending ? "Verifying…" : inv.verification?.passed ? "Outcome verified" : "Verify simulated outcome"}</button></section>}</div></div>
  </div>;
}
function EvidenceTab({ incident, investigation }: { incident: Incident; investigation: Investigation }) { return <><div className="mb-5"><p className="text-sm leading-relaxed text-muted-foreground">{incident.summary}</p></div><div className="space-y-2">{investigation.evidence.map((e) => <div key={e.id} data-testid={`card-evidence-${e.id}`} className="rounded border border-border bg-background/35 p-3"><div className="flex flex-wrap items-center gap-2"><Badge>{e.kind}</Badge><span className="text-sm font-medium">{e.label}</span><span className="ml-auto font-mono text-[10px] text-muted-foreground">{when(e.observed_at)}</span></div><p className="mt-2 text-xs leading-relaxed text-muted-foreground">{e.detail}</p><p className="mt-2 font-mono text-[10px] uppercase tracking-wider text-primary/70">source · {e.origin}</p></div>)}</div></>; }
function ReasoningTab({ investigation }: { investigation: Investigation }) { return <div className="space-y-4">{investigation.hypotheses.map((h) => <div key={h.rank} data-testid={`card-hypothesis-${h.rank}`} className="rounded border border-border bg-background/35 p-4"><div className="flex items-center gap-3"><span className="font-mono text-xs text-primary">0{h.rank}</span><p className="flex-1 text-sm font-medium">{h.statement}</p><Badge>{h.confidence}</Badge></div><p className="mt-3 text-xs leading-relaxed text-muted-foreground">{h.rationale}</p><div className="mt-3 grid gap-3 text-xs sm:grid-cols-2"><div><p className="mb-1 font-mono text-[10px] uppercase text-emerald-300">Supporting</p>{h.supporting.map((x) => <p key={x} className="text-muted-foreground">+ {x}</p>)}</div><div><p className="mb-1 font-mono text-[10px] uppercase text-rose-300">Contradicting</p>{h.contradicting.map((x) => <p key={x} className="text-muted-foreground">− {x}</p>)}</div></div></div>)}</div>; }
function HindsightTab({ investigation }: { investigation: Investigation }) { return <div className="space-y-5"><div className="rounded border border-violet-300/20 bg-violet-300/[.05] p-4"><div className="flex items-center gap-2 text-xs font-semibold text-violet-200"><BrainCircuit className="h-4 w-4" /> Model reasoning with Hindsight</div><p className="mt-3 text-sm leading-relaxed text-muted-foreground">{investigation.after_recall_analysis}</p></div><div className="space-y-2">{investigation.memories.map((m) => <div key={m.id} data-testid={`card-memory-${m.id}`} className="rounded border border-border bg-background/35 p-3"><div className="flex items-center justify-between gap-2"><p className="text-sm font-medium">{m.title}</p><Badge>{m.relevance}</Badge></div><p className="mt-2 text-xs text-muted-foreground">{m.content}</p><div className="mt-2 flex flex-wrap items-center justify-between gap-2 font-mono text-[10px] uppercase tracking-wider text-violet-200/70"><span>hindsight · {m.service}</span><span className="text-muted-foreground">{m.source}</span></div></div>)}</div></div>; }
function TraceTab({ trace, loading }: { trace?: { nodes: Array<Record<string, unknown>> }; loading: boolean }) { if (loading) return <LoadingPanel label="Resolving memory trace" />; if (!trace?.nodes?.length) return <EmptyPanel title="No trace available" detail="The explainable memory path will appear when the investigation has run." />; return <div className="space-y-2">{trace.nodes.map((node, index) => <div key={index} data-testid={`trace-node-${index}`} className="flex gap-3 rounded border border-border bg-background/35 p-3"><span className="font-mono text-xs text-primary">0{index + 1}</span><pre className="overflow-auto whitespace-pre-wrap text-xs text-muted-foreground">{JSON.stringify(node, null, 2)}</pre></div>)}</div>; }
function TimelineTab({ investigation }: { investigation: Investigation }) { return <div className="space-y-0">{investigation.steps.map((s, index) => <div key={s.name} className="flex gap-4"><div className="flex flex-col items-center"><div className={cx('mt-1 h-2.5 w-2.5 rounded-full', s.status === 'complete' || s.status === 'completed' ? 'bg-emerald-300' : 'bg-primary')} /><div className="h-full w-px bg-border" /></div><div className="pb-6"><p className="text-sm font-medium">{s.label}</p><p className="mt-1 text-xs text-muted-foreground">{s.detail}</p></div></div>)}</div>; }

function PostmortemEmbed({ incidentId }: { incidentId: string }) { const pm = useGetPostmortem(incidentId, { query: { queryKey: getGetPostmortemQueryKey(incidentId), enabled: Boolean(incidentId) } }); if (pm.isLoading) return <LoadingPanel label="Loading post-mortem" />; if (pm.isError || !pm.data) return <EmptyPanel title="No post-mortem yet" detail="Open the post-mortems workspace to create or review the record." />; return <div data-testid={`card-postmortem-${incidentId}`} className="space-y-4 text-sm"><p className="font-display text-2xl">{pm.data.summary}</p><div><p className="font-mono text-[10px] uppercase tracking-wider text-primary">Root cause</p><p className="mt-1 text-muted-foreground">{pm.data.root_cause}</p></div><Link href="/postmortems" data-testid="link-open-postmortems" className="inline-flex items-center gap-2 text-xs text-primary hover:underline">Open post-mortem workspace <ArrowRight className="h-3.5 w-3.5" /></Link></div>; }

function MemoryPage() {
  const [q, setQ] = useState(''); const [selected, setSelected] = useState(''); const [reflect, setReflect] = useState(''); const [result, setResult] = useState('');
  const memories = useListMemories(q ? { q } : undefined); const detail = useGetMemory(selected, { query: { queryKey: getGetMemoryQueryKey(selected), enabled: Boolean(selected) } }); const reflection = useReflectMemories();
  const submitReflect = () => { if (reflect.trim()) reflection.mutate({ data: { query: reflect } }, { onSuccess: (r) => setResult(r.text) }); };
  return <div className="mx-auto max-w-[1500px]"><PageTitle eyebrow="03 / engineering memory" title="Memory explorer" detail="Search what the organization has learned. Inspect the source before it influences a decision." /><div className="grid gap-6 xl:grid-cols-[.9fr_1.1fr]"><section><div className="relative"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><input data-testid="input-search-memory" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search memory by incident, service, cause" className="h-10 w-full rounded border border-input bg-card pl-9 pr-3 text-sm outline-none focus:border-primary" /></div><div className="mt-4">{memories.isLoading ? <LoadingPanel label="Searching Hindsight" /> : memories.isError ? <ErrorPanel onRetry={() => memories.refetch()} /> : !memories.data?.length ? <EmptyPanel title="No memories found" detail="Try a different query. New retained post-mortems appear here after review." /> : <div className="space-y-2">{memories.data.map((m) => <button key={m.id} data-testid={`button-memory-${m.id}`} onClick={() => setSelected(m.id)} className={cx('w-full rounded border p-4 text-left transition-colors', selected === m.id ? 'border-primary/50 bg-primary/[.07]' : 'border-border bg-card/70 hover:border-primary/30')}><div className="flex items-start justify-between gap-3"><div><p className="font-medium">{m.title}</p><p className="mt-1 text-xs text-muted-foreground">{m.service} · {when(m.created_at)}</p></div><Badge>{m.outcome}</Badge></div><p className="mt-3 line-clamp-2 text-xs leading-relaxed text-muted-foreground">{m.content}</p></button>)}</div>}</div></section><section className="space-y-5"><div className="rounded-lg border border-violet-300/20 bg-violet-300/[.05] p-5"><SectionHeading icon={Sparkles} label="Ask Hindsight to reflect" meta="synthesis" /><div className="flex gap-2"><input data-testid="input-reflect-memory" value={reflect} onChange={(e) => setReflect(e.target.value)} placeholder="What patterns recur across checkout incidents?" className="h-9 flex-1 rounded border border-input bg-background/60 px-3 text-sm outline-none focus:border-primary" /><button disabled={reflection.isPending || !reflect.trim()} data-testid="button-reflect-memory" onClick={submitReflect} className="rounded bg-violet-300 px-3 text-xs font-bold text-slate-950 disabled:opacity-40">{reflection.isPending ? 'Reflecting…' : 'Reflect'}</button></div>{result && <div className="mt-4 rounded border border-violet-300/20 bg-background/35 p-3 text-sm leading-relaxed text-violet-100" data-testid="text-reflection-result">{result}</div>}</div>{selected && detail.data && <div className="rounded-lg border border-border/70 bg-card/75 p-5" data-testid={`panel-memory-detail-${selected}`}><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-widest text-primary">Selected memory</p><h2 className="mt-2 font-display text-2xl">{detail.data.hindsight.title}</h2></div><button data-testid="button-close-memory-detail" onClick={() => setSelected('')} className="rounded p-1 text-muted-foreground hover:bg-muted"><X className="h-4 w-4" /></button></div><p className="mt-4 text-sm leading-relaxed text-muted-foreground">{detail.data.hindsight.content}</p><div className="mt-5 grid gap-3 border-t border-border/60 pt-4 sm:grid-cols-2"><div><p className="font-mono text-[10px] uppercase text-muted-foreground">Root cause</p><p className="mt-1 text-sm">{detail.data.hindsight.root_cause}</p></div><div><p className="font-mono text-[10px] uppercase text-muted-foreground">Source</p><p className="mt-1 text-sm">{detail.data.hindsight.source}</p></div></div></div>}</section></div></div>;
}

function PostmortemsPage() {
  const incidents = useListIncidents(); const [selected, setSelected] = useState(''); const pm = useGetPostmortem(selected, { query: { queryKey: getGetPostmortemQueryKey(selected), enabled: Boolean(selected) } }); const save = useUpdatePostmortem(); const retain = useRetainPostmortem();
  const [form, setForm] = useState({ summary: '', root_cause: '', timeline: '', lessons_learned: '', actions_taken: '' });
  const [reviewPending, setReviewPending] = useState(false);
  const [reviewedNotice, setReviewedNotice] = useState(false);
  const choose = (i: Incident) => { setSelected(i.id); setForm({ summary: '', root_cause: '', timeline: '', lessons_learned: '', actions_taken: '' }); setReviewedNotice(false); };
  const submit = (e: React.FormEvent) => { e.preventDefault(); save.mutate({ incidentId: selected, data: form }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetPostmortemQueryKey(selected) }) }); };
  const handleReview = async () => {
    setReviewPending(true);
    try {
      const res = await fetch(`/api/incidents/${selected}/postmortem/review`, { method: 'POST' });
      if (res.ok) {
        setReviewedNotice(true);
        await queryClient.invalidateQueries({ queryKey: getGetPostmortemQueryKey(selected) });
      }
    } finally {
      setReviewPending(false);
    }
  };
  return <div className="mx-auto max-w-[1500px]"><PageTitle eyebrow="04 / learning loop" title="Post-mortems" detail="Turn a resolved incident into durable context. Retention is a deliberate operator action." /><div className="grid gap-6 xl:grid-cols-[.65fr_1.35fr]"><section><SectionHeading icon={FileText} label="Incident records" meta="select to edit" />{incidents.isLoading ? <LoadingPanel /> : incidents.isError ? <ErrorPanel onRetry={() => incidents.refetch()} /> : <div className="space-y-2">{(incidents.data || []).map((i) => <button key={i.id} data-testid={`button-select-postmortem-${i.id}`} onClick={() => choose(i)} className={cx('w-full rounded border p-3 text-left', selected === i.id ? 'border-primary/50 bg-primary/[.07]' : 'border-border bg-card/70 hover:border-primary/30')}><div className="flex items-center gap-2"><span className={cx('h-1.5 w-1.5 rounded-full', i.status === 'resolved' ? 'bg-emerald-300' : 'bg-amber-300')} /><span className="flex-1 truncate text-sm">{i.title}</span><span className="font-mono text-[10px] text-muted-foreground">{i.public_id}</span></div><p className="mt-1 pl-3.5 text-xs text-muted-foreground">{i.status} · {i.service}</p></button>)}</div>}</section><section>{!selected ? <EmptyPanel title="Select an incident" detail="Choose an incident to inspect its post-mortem record and retention status." /> : pm.isLoading ? <LoadingPanel label="Loading post-mortem editor" /> : <form onSubmit={submit} className="rounded-lg border border-border/70 bg-card/75 p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="font-mono text-[10px] uppercase tracking-widest text-primary">Editor · {selected}</p><h2 className="mt-1 font-display text-2xl">Incident reflection</h2></div>{pm.data && <div className="flex items-center gap-2"><Badge><span className={pm.data.review_status === 'reviewed' ? 'text-emerald-200' : 'text-amber-200'}>{pm.data.review_status === 'reviewed' ? 'reviewed' : 'draft (review required)'}</span></Badge><Badge><span className={tone(pm.data.retention_status)}>{pm.data.retention_status}</span></Badge></div>}</div>{pm.data && pm.data.review_status !== 'reviewed' && <div data-testid="banner-review-required" className="mt-4 rounded border border-amber-300/30 bg-amber-300/[.07] p-3 text-xs text-amber-200">Review gate: Review and save the root cause, lessons learned, and actions before retaining into organizational memory.</div>}<div className="mt-5 grid gap-4">{[['summary','Summary'],['root_cause','Root cause'],['timeline','Timeline'],['lessons_learned','Lessons learned'],['actions_taken','Actions taken']].map(([key,label]) => <label key={key} className="text-xs font-medium text-muted-foreground">{label}<textarea data-testid={`textarea-postmortem-${key}`} value={form[key as keyof typeof form] || (pm.data?.[key as keyof Postmortem] as string) || ''} onChange={(e) => setForm({ ...form, [key]: e.target.value })} className="mt-1.5 min-h-16 w-full rounded border border-input bg-background/45 p-3 text-sm text-foreground outline-none focus:border-primary" /></label>)}</div><div className="mt-5 flex flex-wrap items-center gap-2"><button disabled={save.isPending} data-testid="button-save-postmortem" className="rounded border border-border bg-card px-4 py-2 text-xs font-semibold hover:bg-muted disabled:opacity-50">{save.isPending ? 'Saving draft…' : 'Save draft'}</button>{pm.data?.review_status !== 'reviewed' && <button type="button" disabled={reviewPending || !pm.data} data-testid="button-review-postmortem" onClick={handleReview} className="inline-flex items-center gap-2 rounded bg-primary px-4 py-2 text-xs font-bold text-primary-foreground disabled:opacity-50"><CheckCircle2 className="h-3.5 w-3.5" />{reviewPending ? 'Approving…' : 'Approve & Mark Reviewed'}</button>}<button type="button" disabled={retain.isPending || !pm.data || pm.data.review_status !== 'reviewed'} data-testid="button-retain-postmortem" title={pm.data?.review_status !== 'reviewed' ? 'Please review and save post-mortem before retaining' : 'Retain verified lesson in memory'} onClick={() => retain.mutate({ incidentId: selected }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetPostmortemQueryKey(selected) }) })} className="inline-flex items-center gap-2 rounded border border-emerald-300/30 px-4 py-2 text-xs font-semibold text-emerald-200 disabled:opacity-40"><Archive className="h-3.5 w-3.5" /> Retain in memory</button></div>{save.isSuccess && <p data-testid="status-postmortem-saved" className="mt-3 text-xs text-muted-foreground">Draft changes saved.</p>}{reviewedNotice && <p data-testid="status-postmortem-reviewed" className="mt-3 text-xs text-emerald-300">Post-mortem approved and marked as reviewed. It can now be retained into memory.</p>}{retain.isError && <p data-testid="status-retain-error" className="mt-3 text-xs text-rose-300">Retention rejected: {(retain.error as any)?.message || 'Post-mortem must be verified and reviewed before retention.'}</p>}</form>}</section></div></div>;
}

function DemoPage() {
  const scenarios = useListDemoScenarios(); const load = useLoadDemo(); const reset = useResetDemo(); const [result, setResult] = useState('');
  return <div className="mx-auto max-w-[1200px]"><PageTitle eyebrow="05 / demo lab" title="Guided demo lab" detail="Load a known incident shape to see live evidence, reasoning, memory recall, and verified simulation in sequence." action={<div className="flex gap-2"><button disabled={load.isPending} data-testid="button-load-demo" onClick={() => load.mutate(undefined, { onSuccess: (r) => setResult(r.message) })} className="inline-flex items-center gap-2 rounded bg-primary px-3.5 py-2 text-xs font-bold text-primary-foreground"><Play className="h-3.5 w-3.5" /> Load scenario</button><button disabled={reset.isPending} data-testid="button-reset-demo" onClick={() => reset.mutate({ data: { confirm: true } }, { onSuccess: (r) => setResult(r.message) })} className="inline-flex items-center gap-2 rounded border border-border px-3.5 py-2 text-xs font-semibold hover:bg-muted"><RefreshCw className="h-3.5 w-3.5" /> Reset</button></div>} />{result && <div data-testid="status-demo-result" className="mb-5 rounded border border-emerald-300/25 bg-emerald-300/[.06] p-3 text-sm text-emerald-200">{result}</div>}<div className="grid gap-4">{scenarios.isLoading ? <LoadingPanel label="Loading demo scenarios" /> : scenarios.isError ? <ErrorPanel onRetry={() => scenarios.refetch()} /> : !scenarios.data?.length ? <EmptyPanel title="No scenarios available" detail="The demo catalog is empty in this fixture environment." /> : scenarios.data.map((s) => <div key={s.key} data-testid={`card-scenario-${s.key}`} className="rounded-lg border border-border/70 bg-card/75 p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><span className="font-mono text-[10px] uppercase tracking-widest text-primary">{s.key}</span>{s.loaded && <Badge><span className="text-emerald-200">loaded</span></Badge>}</div><h2 className="mt-2 font-display text-2xl">{s.title}</h2><p className="mt-1 text-sm text-muted-foreground">{s.service} · {s.severity}</p></div><div className="rounded border border-border bg-background/45 px-3 py-2 text-right"><p className="font-mono text-[10px] uppercase text-muted-foreground">Recall path</p><p className="mt-1 text-xs">before → after</p></div></div><p className="mt-4 max-w-3xl text-sm leading-relaxed text-muted-foreground">{s.description}</p></div>)}</div></div>;
}

function SettingsPage() {
  const health = useHealthCheck(); const integrations = useGetIntegrationStatus();
  return <div className="mx-auto max-w-[1100px]"><PageTitle eyebrow="06 / system configuration" title="Settings" detail="Confirm the boundaries around this console before relying on a result." /><div className="grid gap-6 md:grid-cols-2"><section className="rounded-lg border border-border/70 bg-card/75 p-5"><SectionHeading icon={Activity} label="API health" /><div className="flex items-center gap-3 rounded border border-border bg-background/35 p-4"><span className={cx('h-2.5 w-2.5 rounded-full', health.data?.status === 'ok' ? 'bg-emerald-300' : 'bg-amber-300')} /><div><p className="text-sm font-medium" data-testid="status-api-health">{health.data?.status || (health.isLoading ? 'Checking…' : 'Unavailable')}</p><p className="mt-1 font-mono text-[10px] text-muted-foreground">{health.data ? `version ${health.data.version} · db ${health.data.db}` : 'No health response'}</p></div></div></section><section className="rounded-lg border border-border/70 bg-card/75 p-5"><SectionHeading icon={SlidersHorizontal} label="Runtime boundary" /><div className="space-y-3 text-sm"><div className="flex justify-between border-b border-border/60 pb-3"><span className="text-muted-foreground">Environment</span><span className="font-mono text-xs text-amber-200">simulated fixtures</span></div><div className="flex justify-between border-b border-border/60 pb-3"><span className="text-muted-foreground">Remediation</span><span className="font-mono text-xs text-amber-200">approval required</span></div><div className="flex justify-between"><span className="text-muted-foreground">Evidence labeling</span><span className="font-mono text-xs text-emerald-200">enforced</span></div></div></section></div><section className="mt-6 rounded-lg border border-border/70 bg-card/75 p-5"><SectionHeading icon={Network} label="Integration health" meta="configured services" />{integrations.isLoading ? <LoadingPanel label="Checking integrations" /> : integrations.isError ? <ErrorPanel onRetry={() => integrations.refetch()} /> : !integrations.data?.length ? <EmptyPanel title="No integrations configured" detail="The API returned an empty integration inventory." /> : <div className="grid gap-2 md:grid-cols-2">{integrations.data.map((x) => {
    const isHindsight = x.name === 'Hindsight';
    const badgeLabel = isHindsight
      ? (x.configured && x.reachable ? 'connected real hindsight' : x.configured ? 'remote service error' : 'simulated fallback')
      : (x.configured && x.reachable ? 'healthy' : x.configured ? 'configured' : 'not configured');
    const badgeColor = isHindsight
      ? (x.configured && x.reachable ? 'text-emerald-200' : x.configured ? 'text-rose-200' : 'text-amber-200')
      : (x.configured && x.reachable ? 'text-emerald-200' : x.configured ? 'text-amber-200' : 'text-muted-foreground');
    const iconColor = isHindsight
      ? (x.configured && x.reachable ? 'bg-emerald-300/10 text-emerald-200' : x.configured ? 'bg-rose-500/10 text-rose-200' : 'bg-amber-300/10 text-amber-200')
      : (x.configured && x.reachable ? 'bg-emerald-300/10 text-emerald-200' : 'bg-amber-300/10 text-amber-200');

    return (
      <div key={x.name} data-testid={`row-integration-${x.name}`} className="flex items-center gap-3 rounded border border-border bg-background/35 p-4">
        <div className={cx('grid h-8 w-8 place-items-center rounded', iconColor)}>
          <Database className="h-4 w-4" />
        </div>
        <div className="min-w-0 flex-1">
          <p className="text-sm font-medium">{x.name}</p>
          <p className="mt-1 truncate text-xs text-muted-foreground">{x.detail}</p>
        </div>
        <Badge>
          <span className={badgeColor}>{badgeLabel}</span>
        </Badge>
      </div>
    );
  })}</div>}</section></div>;
}

function Router() { const [location] = useLocation(); return <ErrorBoundary resetKey={location}><Shell><Switch><Route path="/" component={Overview} /><Route path="/incidents" component={IncidentsPage} /><Route path="/investigation/:incidentId" component={InvestigationPage} /><Route path="/memory" component={MemoryPage} /><Route path="/postmortems" component={PostmortemsPage} /><Route path="/demo" component={DemoPage} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch></Shell></ErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><Router /><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;